syntax = "proto3";

package shop;

message UpdateStockRequest {
  string sku = 1;
  int32 quantity = 2;
  string note = 3;
}

#include "shop/stock.pb.h"

#include "inventory.h"

void ApplyUpdate(const shop::UpdateStockRequest& req, Inventory& inv) {
  if (req.quantity() != 0) {
    inv.SetQuantity(req.sku(), req.quantity());
  }
  if (!req.note().empty()) {
    inv.SetNote(req.sku(), req.note());
  }
}

