void FillUpdate(shop::UpdateStockRequest& req, const std::string& sku,
                std::optional<std::int32_t> quantity) {
  req.set_sku(sku);
  if (quantity) {
    req.set_quantity(*quantity);
  } else {
    req.clear_quantity();
  }
}
